create table ad_accounts(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,provider text not null check(provider in ('meta','google')),name text not null,external_id text not null,version text not null default 'v26',currency text,time_zone text,credentials jsonb not null default '{}',oauth_nonce text,oauth_expires timestamptz,oauth_actor int references users,checked_at timestamptz,synced_at timestamptz,error text,unique(tenant_id,provider,external_id));
create table ad_campaigns(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,account_id int not null references ad_accounts,name text not null,spec jsonb not null default '{}',remote_id text,status text not null default 'draft',phase int not null default 0,resources jsonb not null default '{}',last_error text,version int not null default 1,created_by int references users,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(account_id,remote_id));
create table ad_metrics(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,account_id int not null references ad_accounts,campaign_id int not null references ad_campaigns,day date not null,currency text not null,spend numeric not null default 0,impressions bigint not null default 0,clicks bigint not null default 0,conversions numeric,conversion_value numeric,reach bigint,updated_at timestamptz not null default now(),unique(campaign_id,day));
create table ad_actions(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,campaign_id int not null references ad_campaigns,actor_id int references users,type text not null,status text not null default 'sending',detail text,created_at timestamptz not null default now());
do $$declare r record;begin for r in select * from(values('ad_accounts','users,oauth_actor'),('ad_campaigns','ad_accounts,account_id,users,created_by'),('ad_metrics','ad_accounts,account_id,ad_campaigns,campaign_id'),('ad_actions','ad_campaigns,campaign_id,users,actor_id')) v(t,refs) loop execute format('alter table %I enable row level security',r.t);execute format('alter table %I force row level security',r.t);execute format('create policy tenant_iso on %I using(tenant_id=nullif(current_setting(''app.tenant'',true),'''')::int) with check(tenant_id=nullif(current_setting(''app.tenant'',true),'''')::int)',r.t);execute format('create trigger fk_guard before insert or update on %I for each row execute function fk_guard(%s)',r.t,(select string_agg(quote_literal(x),',') from unnest(string_to_array(r.refs,',')) x));end loop;end $$;
create index ad_metric_period on ad_metrics(tenant_id,day,account_id);
alter table ad_accounts add column synced_from date;
alter table ad_accounts add column synced_to date;
